      fileType: z.string().regex(/^(image\/(jpeg|jpg|png|gif|webp)|video\/(mp4|webm|mov))$/, "\uC9C0\uC6D0\uB418\uC9C0 \uC54A\uB294 \uD30C\uC77C \uD615\uC2DD\uC785\uB2C8\uB2E4"),
      fileSize: z.number().int().positive("\uD30C\uC77C \uD06C\uAE30\uB294 \uC591\uC218\uC5EC\uC57C \uD569\uB2C8\uB2E4").optional(),
      width: z.number().int().positive().optional(),
