function calculateFallbackPrice(curriculum) {
  const baseRatePerHour = 2e4;
  const totalHours = curriculum.duration / 60;
  const difficultyMultiplier = {
    beginner: 0.9,
    intermediate: 1,
    advanced: 1.2
  };
  let price = baseRatePerHour * totalHours * difficultyMultiplier[curriculum.difficulty];
  if (curriculum.modules.length > 6) {
    price *= 1.05;
  }
  if (curriculum.modules.length > 8) {
    price *= 1.1;
  }
  price = Math.max(19e3, Math.min(5e5, Math.round(price / 1e3) * 1e3));
  return price;
}
