// server/middleware/upload.ts
init_audit_logger();
import multer from "multer";
import path4 from "path";
import fs4 from "fs";
var uploadsDir = path4.join(process.cwd(), "public", "uploads");
if (!fs4.existsSync(uploadsDir)) {
  fs4.mkdirSync(uploadsDir, { recursive: true });
}
var fileFilter = (req2, file, cb) => {
  const imageTypes = /jpeg|jpg|png|gif|webp/;
  const videoTypes = /mp4|avi|mkv|mov|wmv|flv|webm/;
  const extname = imageTypes.test(path4.extname(file.originalname).toLowerCase()) || videoTypes.test(path4.extname(file.originalname).toLowerCase());
  const mimetype = file.mimetype.startsWith("image/") || file.mimetype.startsWith("video/");
  if (mimetype && extname) {
    return cb(null, true);
  } else {
    cb(new Error("\uD30C\uC77C \uD615\uC2DD\uC774 \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC774\uBBF8\uC9C0 \uB610\uB294 \uB3D9\uC601\uC0C1 \uD30C\uC77C\uB9CC \uC5C5\uB85C\uB4DC \uAC00\uB2A5\uD569\uB2C8\uB2E4."));
  }
};
var documentFilter = (req2, file, cb) => {
  const documentTypes = /hwp|hwpx|doc|docx|pdf|xlsx|xls/;
  const extname = documentTypes.test(path4.extname(file.originalname).toLowerCase());
  if (extname) {
    return cb(null, true);
  } else {
    cb(new Error("\uC9C0\uC6D0\uB418\uC9C0 \uC54A\uB294 \uBB38\uC11C \uD615\uC2DD\uC785\uB2C8\uB2E4. hwp, hwpx, doc, docx, pdf, xlsx, xls \uD30C\uC77C\uB9CC \uC5C5\uB85C\uB4DC \uAC00\uB2A5\uD569\uB2C8\uB2E4."));
  }
};
var storage3 = multer.diskStorage({
  destination: (req2, file, cb) => {
    let uploadPath = uploadsDir;
    if (file.mimetype.startsWith("image/")) {
      uploadPath = path4.join(uploadsDir, "images");
    } else if (file.mimetype.startsWith("video/")) {
      uploadPath = path4.join(uploadsDir, "videos");
    }
    if (!fs4.existsSync(uploadPath)) {
      fs4.mkdirSync(uploadPath, { recursive: true });
    }
    cb(null, uploadPath);
  },
  filename: (req2, file, cb) => {
    const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
    const ext = path4.extname(file.originalname);
    const name = path4.basename(file.originalname, ext);
    cb(null, `${name}-${uniqueSuffix}${ext}`);
  }
});
var limits = {
  fileSize: 50 * 1024 * 1024,
  // 50MB
  files: 10
  // 최대 10개 파일
};
var uploadSingle = multer({
  storage: storage3,
  fileFilter,
  limits: { fileSize: 5 * 1024 * 1024 }
  // 단일 파일: 5MB
}).single("file");
var uploadMultiple = multer({
  storage: storage3,
  fileFilter,
  limits
}).array("files", 10);
var uploadFields = multer({
  storage: storage3,
  fileFilter,
  limits
}).fields([
  { name: "photos", maxCount: 8 },
  { name: "videos", maxCount: 3 },
  { name: "avatar", maxCount: 1 }
]);
var processUploadedFiles = (files2) => {
  if (!files2) return null;
  const processFile = (file) => ({
    filename: file.filename,
    originalName: file.originalname,
    path: file.path.replace(process.cwd() + "/public", ""),
    size: file.size,
    mimetype: file.mimetype,
    url: file.path.replace(process.cwd() + "/public", "")
  });
  if (Array.isArray(files2)) {
    return files2.map(processFile);
  }
  if ("fieldname" in files2) {
    return processFile(files2);
  }
  const result = {};
  for (const [fieldname, fileArray] of Object.entries(files2)) {
    result[fieldname] = fileArray.map(processFile);
  }
  return result;
};
var uploadDocuments = multer({
  storage: multer.diskStorage({
    destination: (req2, file, cb) => {
      const docPath = path4.join(uploadsDir, "documents");
      if (!fs4.existsSync(docPath)) {
        fs4.mkdirSync(docPath, { recursive: true });
      }
      cb(null, docPath);
    },
    filename: (req2, file, cb) => {
      let originalName = file.originalname;
      try {
        const buffer = Buffer.from(file.originalname, "latin1");
        const decoded = buffer.toString("utf8");
        if (decoded && !decoded.includes("\uFFFD")) {
          originalName = decoded;
        }
      } catch (e) {
        originalName = file.originalname;
      }
      const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
      const ext = path4.extname(originalName);
      const name = path4.basename(originalName, ext);
      cb(null, `${name}-${uniqueSuffix}${ext}`);
    }
  }),
  fileFilter: documentFilter,
  limits: { fileSize: 10 * 1024 * 1024 }
  // 10MB 제한
}).array("files", 5);
var deleteFile = (filePath) => {
  try {
    const fullPath = path4.join(process.cwd(), "public", filePath);
    if (fs4.existsSync(fullPath)) {
      fs4.unlinkSync(fullPath);
      return true;
    }
    return false;
  } catch (error) {
    logServerError("\uD30C\uC77C \uC0AD\uC81C \uC624\uB958:", error);
    return false;
  }
};

