function getSessionUser(req2) {
  const sessionUser = req2.session?.user;
  if (!sessionUser || typeof sessionUser.id !== "number") return null;
  return {
    id: sessionUser.id,
    role: String(sessionUser.role || ""),
    name: sessionUser.name,
    email: sessionUser.email
  };
}
function requireAuth(req2, res, next) {
  const user = getSessionUser(req2);
  if (!user) return res.status(401).json({ success: false, error: "\uB85C\uADF8\uC778\uC774 \uD544\uC694\uD569\uB2C8\uB2E4." });
  req2.authUser = user;
  next();
}
function requireRole(...roles) {
  return (req2, res, next) => {
    const user = getSessionUser(req2);
    if (!user) return res.status(401).json({ success: false, error: "\uB85C\uADF8\uC778\uC774 \uD544\uC694\uD569\uB2C8\uB2E4." });
    if (!roles.includes(user.role)) {
      return res.status(403).json({ success: false, error: "\uAD8C\uD55C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4." });
    }
    req2.authUser = user;
    next();
  };
}
