router5.post("/admin/settle/:revenueId", async (req2, res) => {
  try {
    const revenueId = parseInt(req2.params.revenueId);
    const [revenue] = await db.select().from(monthlyRevenue).where(eq17(monthlyRevenue.id, revenueId));
    if (!revenue) {
      return res.status(404).json({ error: "Revenue not found" });
    }
    if (revenue.isSettled) {
      return res.status(400).json({ error: "Already settled" });
    }
    const trainers2 = await db.select({
      userId: talezScoreCache.userId,
      trainerScore: talezScoreCache.trainerScore
    }).from(talezScoreCache).innerJoin(users, eq17(users.id, talezScoreCache.userId)).where(and16(
      eq17(users.role, "trainer"),
      eq17(talezScoreCache.monetizationEnabled, true)
    ));
    if (trainers2.length === 0) {
      return res.status(400).json({ error: "No eligible trainers" });
    }
    const totalScore = trainers2.reduce((sum2, t) => sum2 + Number(t.trainerScore || 0), 0);
    const trainerPool = Number(revenue.totalAmount) * (Number(revenue.trainerShare) / 100);
    const payoutResults = [];
    for (const trainer of trainers2) {
      const score = Number(trainer.trainerScore || 0);
      const ratio = totalScore > 0 ? score / totalScore : 0;
      const grossAmount = trainerPool * ratio;
      const platformFee = grossAmount * (Number(revenue.platformShare) / 100);
      const netAmount = grossAmount - platformFee;
      const [payout] = await db.insert(payouts).values({
        revenueId,
        userId: trainer.userId,
        month: revenue.month,
        grossAmount: String(grossAmount),
        platformFee: String(platformFee),
        netAmount: String(netAmount),
        contributionScore: String(score),
        contributionRatio: String(ratio),
        status: "pending"
      }).returning();
      payoutResults.push(payout);
    }
    await db.update(monthlyRevenue).set({ isSettled: true, settledAt: /* @__PURE__ */ new Date() }).where(eq17(monthlyRevenue.id, revenueId));
    res.json({ success: true, payouts: payoutResults });
  } catch (error) {
    logServerError("Settlement error:", error, req2);
    res.status(500).json({ error: "Failed to settle" });
  }
});
