var verifyNoseRateLimit = /* @__PURE__ */ new Map();
var RATE_LIMIT_WINDOW_MS = 60 * 1e3;
var RATE_LIMIT_MAX_REQUESTS = 10;
function rateLimitVerifyNose(req2, res, next) {
  const ip = req2.ip || req2.connection?.remoteAddress || "unknown";
  const token = req2.params.token || "no-token";
  const key = `${ip}:${token}`;
  const now = Date.now();
  const entry = verifyNoseRateLimit.get(key);
  if (entry && entry.resetAt > now) {
    if (entry.count >= RATE_LIMIT_MAX_REQUESTS) {
      return res.status(429).json({ success: false, error: "\uC694\uCCAD\uC774 \uB108\uBB34 \uB9CE\uC2B5\uB2C8\uB2E4. \uC7A0\uC2DC \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD574\uC8FC\uC138\uC694." });
    }
    entry.count++;
  } else {
    verifyNoseRateLimit.set(key, { count: 1, resetAt: now + RATE_LIMIT_WINDOW_MS });
  }
  if (verifyNoseRateLimit.size > 1e4) {
    for (const [k, v] of verifyNoseRateLimit) {
      if (v.resetAt <= now) verifyNoseRateLimit.delete(k);
    }
  }
  next();
}
var noseUploadDir = path7.join(process.cwd(), ".private/uploads/nose");
