  if (text2.length > 2e4) {
    console.log(`[\uD30C\uC77C\uD30C\uC11C] \uD14D\uC2A4\uD2B8 \uAE38\uC774 \uC81C\uD55C \uC801\uC6A9: ${text2.length} -> 20,000\uC790`);
  }
