  app2.post("/api/admin/notifications/send", requireAuth5("admin"), csrfProtection, async (req2, res) => {
    try {
      const sendSchema = z9.object({
        category: z9.enum(["message", "reservation", "payment", "system", "training"]),
        title: z9.string().trim().min(1).max(200),
        message: z9.string().trim().min(1).max(2e3),
        actionUrl: z9.string().trim().max(500).optional().nullable(),
        targetType: z9.enum(["users", "role", "all"]),
        userIds: z9.array(z9.number().int().positive()).optional(),
        role: z9.enum(["admin", "trainer", "institute-admin", "institute", "pet-owner"]).optional()
      });
      const parsed = sendSchema.safeParse(req2.body);
      if (!parsed.success) {
        return res.status(400).json({
          success: false,
          message: "\uC785\uB825\uAC12\uC774 \uC62C\uBC14\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
          errors: parsed.error.flatten()
        });
      }
      const data = parsed.data;
      const categoryToType = {
        message: "message",
        reservation: "reservation",
        payment: "payment",
        system: "system",
        training: "training"
      };
      const notifType = categoryToType[data.category];
      let targetUserIds = [];
      if (data.targetType === "users") {
        if (!data.userIds || data.userIds.length === 0) {
          return res.status(400).json({ success: false, message: "\uB300\uC0C1 \uC0AC\uC6A9\uC790\uB97C \uC120\uD0DD\uD558\uC138\uC694." });
        }
        targetUserIds = Array.from(new Set(data.userIds));
      } else if (data.targetType === "role") {
        if (!data.role) {
          return res.status(400).json({ success: false, message: "\uB300\uC0C1 \uC5ED\uD560\uC744 \uC120\uD0DD\uD558\uC138\uC694." });
        }
        const allUsers = await storage2.getAllUsers();
        const wanted = data.role === "institute" ? "institute-admin" : data.role;
        targetUserIds = (allUsers ?? []).filter((u) => !!u && u.role === wanted && u.isActive !== false).map((u) => u.id);
      } else {
        const allUsers = await storage2.getAllUsers();
        targetUserIds = (allUsers ?? []).filter((u) => !!u && u.isActive !== false).map((u) => u.id);
      }
      if (targetUserIds.length === 0) {
        return res.status(400).json({ success: false, message: "\uB300\uC0C1 \uC0AC\uC6A9\uC790\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4." });
      }
      const actionUrl = data.actionUrl && data.actionUrl.length > 0 ? data.actionUrl : void 0;
      const sentBy = req2.user && typeof req2.user.id === "number" ? req2.user.id : null;
      let success = 0;
      let failed = 0;
      const failures = [];
      for (const uid of targetUserIds) {
        try {
          await notificationService.sendNotification({
            userId: uid,
            type: notifType,
            title: data.title,
            message: data.message,
            actionUrl,
            data: { sentBy, source: "admin-broadcast" }
          });
          success += 1;
        } catch (err) {
          failed += 1;
          const errorMessage = err instanceof Error ? err.message : "unknown error";
          failures.push({ userId: uid, error: errorMessage });
          logServerError("[Admin Notification] \uBC1C\uC1A1 \uC2E4\uD328", err, req2);
        }
      }
      return res.json({
        success: true,
        total: targetUserIds.length,
        successCount: success,
        failedCount: failed,
        failures: failures.slice(0, 20),
        message: `\uBC1C\uC1A1 \uC644\uB8CC: \uC131\uACF5 ${success}\uAC74 / \uC2E4\uD328 ${failed}\uAC74 (\uCD1D ${targetUserIds.length}\uBA85)`
      });
    } catch (error) {
      logServerError("[Admin Notification] \uBC1C\uC1A1 \uCC98\uB9AC \uC624\uB958", error, req2);
      return res.status(500).json({ success: false, message: "\uC54C\uB9BC \uBC1C\uC1A1 \uC911 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4." });
    }
  });
