        console.log("\uC774\uBCA4\uD2B8 \uD14C\uC774\uBE14 \uC870\uD68C \uC2E4\uD328 (\uD14C\uC774\uBE14\uC774 \uC5C6\uC744 \uC218 \uC788\uC74C):", dbError.message);
        eventsList = [];
