  async function handleUserSearch(query, res) {
    try {
      if (!query || typeof query !== "string") {
        return res.status(400).json({
          success: false,
          message: "\uAC80\uC0C9\uC5B4\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4."
        });
      }
      let searchQuery = query;
      try {
        searchQuery = decodeURIComponent(query);
      } catch (e) {
        searchQuery = query;
      }
      try {
        if (searchQuery !== query) {
          searchQuery = searchQuery;
        } else {
          const buffer = Buffer.from(searchQuery, "latin1");
          const decoded = buffer.toString("utf8");
          if (decoded !== searchQuery && decoded.length > 0) {
            searchQuery = decoded;
          }
        }
      } catch (e) {
      }
      searchQuery = searchQuery.trim();
      console.log(`[\uC0AC\uC6A9\uC790 \uAC80\uC0C9] \uC6D0\uBCF8: "${query}" -> \uCC98\uB9AC\uB41C \uAC80\uC0C9\uC5B4: "${searchQuery}"`);
      const allUsers = await storage2.getAllUsers();
      const allTrainers = await storage2.getAllTrainers();
      console.log(`[\uC0AC\uC6A9\uC790 \uAC80\uC0C9] \uC804\uCCB4 \uC0AC\uC6A9\uC790: ${allUsers.length}\uBA85, \uC804\uCCB4 \uD6C8\uB828\uC0AC: ${allTrainers.length}\uBA85`);
      const searchResults = [];
      const matchedUsers = allUsers.filter(
        (user) => user.name.toLowerCase().includes(searchQuery.toLowerCase()) || user.email.toLowerCase().includes(searchQuery.toLowerCase())
      );
      const matchedTrainers = allTrainers.filter(
        (trainer) => trainer.name.toLowerCase().includes(searchQuery.toLowerCase()) || trainer.specialties && trainer.specialties.some(
          (specialty) => specialty.toLowerCase().includes(searchQuery.toLowerCase())
        ) || trainer.bio && trainer.bio.toLowerCase().includes(searchQuery.toLowerCase())
      );
      matchedUsers.forEach((user) => {
        searchResults.push({
          id: user.id,
          name: user.name,
          role: user.role || "pet-owner",
          avatar: user.avatar || null,
          email: user.email
        });
      });
      matchedTrainers.forEach((trainer) => {
        searchResults.push({
          id: trainer.userId || trainer.id + 1e3,
          // 훈련사 ID를 사용자 ID로 매핑
          name: trainer.name,
          role: "trainer",
          avatar: trainer.avatar || trainer.image || null,
          email: trainer.email,
          specialties: trainer.specialties || []
        });
      });
      if (searchQuery.length > 0 && searchQuery.length <= 2) {
        console.log(`[\uC0AC\uC6A9\uC790 \uAC80\uC0C9] \uC9E7\uC740 \uAC80\uC0C9\uC5B4\uB85C \uC804\uCCB4 \uC0AC\uC6A9\uC790 \uD3EC\uD568`);
        allUsers.forEach((user) => {
          const alreadyAdded = searchResults.some((result) => result.id === user.id);
          if (!alreadyAdded) {
            searchResults.push({
              id: user.id,
              name: user.name,
              role: user.role || "pet-owner",
              avatar: user.avatar || null,
              email: user.email
            });
          }
        });
        allTrainers.forEach((trainer) => {
          const trainerId = trainer.userId || trainer.id + 1e3;
          const alreadyAdded = searchResults.some((result) => result.id === trainerId);
          if (!alreadyAdded) {
            searchResults.push({
              id: trainerId,
              name: trainer.name,
              role: "trainer",
              avatar: trainer.avatar || trainer.image || null,
              email: trainer.email,
              specialties: trainer.specialties || []
            });
          }
        });
      }
      console.log(`[\uC0AC\uC6A9\uC790 \uAC80\uC0C9] \uAC80\uC0C9 \uACB0\uACFC: ${searchResults.length}\uBA85`);
      res.json({
        success: true,
        users: searchResults,
        query: searchQuery,
        totalResults: searchResults.length
      });
    } catch (error) {
      logServerError("\uC0AC\uC6A9\uC790 \uAC80\uC0C9 \uC624\uB958:", error, req);
      res.status(500).json({
        success: false,
        message: "\uC0AC\uC6A9\uC790 \uAC80\uC0C9 \uC911 \uC624\uB958\uAC00 \uBC1C\uC0DD\uD588\uC2B5\uB2C8\uB2E4."
      });
    }
  }
