  app2.get("/api/institute/metrics", requireAuth5("institute-admin"), async (req2, res) => {
    try {
      const instituteId = req2.session.user?.instituteId;
      if (!instituteId) {
        return res.json({
          newRegistrations: 0,
          completedCourses: 0,
          issuedCertificates: 0,
          activeCourses: 0,
          newRegistrationsChange: "0%",
          completedCoursesChange: "0%",
          issuedCertificatesChange: "0%",
          activeCoursesChange: "0%"
        });
      }
      const activeCoursesQuery = await db.select({ count: sql15`count(*)` }).from(courses).where(and21(
        eq24(courses.instituteId, instituteId),
        eq24(courses.status, "active")
      ));
      const activeCourses = Number(activeCoursesQuery[0]?.count) || 0;
      const enrollmentsQuery = await db.select({ total: sql15`COALESCE(SUM(${courses.enrollmentCount}), 0)` }).from(courses).where(eq24(courses.instituteId, instituteId));
      const newRegistrations = Number(enrollmentsQuery[0]?.total) || 0;
      const completedCoursesQuery = await db.select({ count: sql15`count(*)` }).from(courses).where(and21(
        eq24(courses.instituteId, instituteId),
        eq24(courses.status, "completed")
      ));
      const completedCourses = Number(completedCoursesQuery[0]?.count) || 0;
      res.json({
        newRegistrations,
        completedCourses,
        issuedCertificates: 0,
        // 수료증 테이블이 없으므로 0
        activeCourses,
        newRegistrationsChange: "+0%",
        completedCoursesChange: "+0%",
        issuedCertificatesChange: "+0%",
        activeCoursesChange: "+0%"
      });
    } catch (error) {
      logServerError("\uAE30\uAD00 \uC8FC\uC694 \uC9C0\uD45C \uC870\uD68C \uC2E4\uD328:", error, req2);
      res.json({
        newRegistrations: 0,
        completedCourses: 0,
        issuedCertificates: 0,
        activeCourses: 0,
        newRegistrationsChange: "0%",
        completedCoursesChange: "0%",
        issuedCertificatesChange: "0%",
        activeCoursesChange: "0%"
      });
    }
  });
