// server/performance/index.ts
init_logger();
import compression from "compression";
function setupPerformance(app2) {
  app2.use(compression({
    filter: (req2, res) => {
      if (req2.headers["x-no-compression"] || res.getHeader("Content-Type")?.toString().includes("image/") || res.getHeader("Content-Type")?.toString().includes("video/")) {
        return false;
      }
      return compression.filter(req2, res);
    },
    threshold: 1024
    // 1KB 이상인 응답만 압축
  }));
  app2.use((req2, res, next) => {
    const startTime = Date.now();
    res.on("finish", () => {
      const duration = Date.now() - startTime;
      if (req2.path.startsWith("/api/")) {
        if (duration > 200) {
          logger.warn(`[\uC131\uB2A5] \uB290\uB9B0 \uC694\uCCAD \uAC10\uC9C0: ${req2.method} ${req2.path} - ${duration}ms`);
        } else {
          logger.debug(`[\uC131\uB2A5] \uC694\uCCAD \uCC98\uB9AC \uC2DC\uAC04: ${req2.method} ${req2.path} - ${duration}ms`);
        }
      }
    });
    next();
  });
  app2.use((req2, res, next) => {
    if (req2.path.match(/\.(css|js|jpg|jpeg|png|gif|ico|svg|woff|woff2|ttf|eot)$/)) {
      res.setHeader("Cache-Control", "public, max-age=2592000");
    } else if (req2.path.startsWith("/api/")) {
      res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate, proxy-revalidate");
      res.setHeader("Pragma", "no-cache");
      res.setHeader("Expires", "0");
    }
    next();
  });
  logger.info("[Performance] \uC131\uB2A5 \uCD5C\uC801\uD654 \uC124\uC815\uC774 \uCD08\uAE30\uD654\uB418\uC5C8\uC2B5\uB2C8\uB2E4.");
}

