async function testTossPayment(amount = 1e3) {
  try {
    const secretKey = process.env.TOSS_SECRET_KEY || "test_sk_example";
    const encodedKey = Buffer.from(secretKey + ":").toString("base64");
    const response = await fetch("https://api.tosspayments.com/v1/payments/confirm", {
      method: "POST",
      headers: {
        "Authorization": `Basic ${encodedKey}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        paymentKey: "test_payment_key_" + Date.now(),
        orderId: "test_order_" + Date.now(),
        amount
      })
    });
    return response.ok;
  } catch (error) {
    logServerError("Toss \uACB0\uC81C \uD14C\uC2A4\uD2B8 \uC624\uB958:", error);
    return false;
  }
}
async function cancelTossPayment2(paymentKey, reason = "\uAD00\uB9AC\uC790 \uCDE8\uC18C") {
  try {
    const secretKey = process.env.TOSS_SECRET_KEY || "test_sk_example";
    const encodedKey = Buffer.from(secretKey + ":").toString("base64");
    const response = await fetch(`https://api.tosspayments.com/v1/payments/${paymentKey}/cancel`, {
      method: "POST",
      headers: {
        "Authorization": `Basic ${encodedKey}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        cancelReason: reason
      })
    });
    return response.ok;
  } catch (error) {
    logServerError("Toss \uACB0\uC81C \uCDE8\uC18C \uC624\uB958:", error);
    return false;
  }
}
