var httpServerRef = null;
var isShuttingDown = false;
async function gracefulShutdown(signal, exitCode = 0) {
  if (isShuttingDown) return;
  isShuttingDown = true;
  console.log(`\u{1F44B} ${signal} received, shutting down gracefully...`);
  const forceExit = setTimeout(() => {
    logger.error("\u26D4 Graceful shutdown timeout, forcing exit");
    process.exit(exitCode === 0 ? 1 : exitCode);
  }, 25e3);
  forceExit.unref();
  try {
    if (httpServerRef) {
      await new Promise((resolve) => {
        httpServerRef.close((err) => {
          if (err) logServerError("HTTP server close error:", err);
          else console.log("\u2705 HTTP server closed (no new connections)");
          resolve();
        });
      });
    }
  } catch (err) {
    logServerError("HTTP shutdown \uC5D0\uB7EC:", err);
  }
  try {
    await closeDatabasePool();
  } catch (err) {
    logServerError("DB pool \uC885\uB8CC \uC5D0\uB7EC:", err);
  }
  clearTimeout(forceExit);
  console.log("\u{1F44B} Shutdown complete");
  process.exit(exitCode);
}
process.on("SIGTERM", () => {
  void gracefulShutdown("SIGTERM");
});
process.on("SIGINT", () => {
  void gracefulShutdown("SIGINT");
});
process.on("uncaughtException", (err) => {
  logServerError("\u{1F6A8} Uncaught Exception:", err);
  void gracefulShutdown("uncaughtException", 1);
});
process.on("unhandledRejection", (reason) => {
  logServerError("\u{1F6A8} Unhandled Promise Rejection:", reason);
  if ((process.env.UNHANDLED_REJECTION_POLICY || "shutdown") === "shutdown") {
    void gracefulShutdown("unhandledRejection", 1);
  }
});
